class Person {
  private String name;
  private boolean active;
  String getName() {
    return name;
  }
  boolean isActive() {
    return this.active;
  }
}

enum Colour {
  RED("r");
  private final String code;
  String getCode() {
    return code;
  }
  Colour(String code) {
    this.code = code + "";
  }
}

class Person {
  private static final Person INSTANCE = new Person();
  private String name = "x";
  private int count;
  static Person getInstance() {
    return INSTANCE;
  }
  String getDisplayName() {
    return name.toUpperCase();
  }
  int getCount() {
    count++;
    return count;
  }
  String getOther(String key) {
    return key;
  }
}

interface Named {
  String getName();
}
record Point(int x) {
  public int getX() {
    return x;
  }
}
